SELECT COUNT(DISTINCT s.arcref) 
FROM scans s
JOIN pointcloud p ON s.arcref = p.arcref;

-- Check if some pointcloud records don't have matching scans or sites
SELECT COUNT(*) FROM pointcloud p 
WHERE NOT EXISTS (SELECT 1 FROM scans s WHERE s.arcref = p.arcref);

-- Check if some scans don't have matching sites
SELECT COUNT(*) FROM scans s 
WHERE NOT EXISTS (SELECT 1 FROM sites si WHERE si.zoneregistry = s.zoneref);

-- Check if scans table has any numeric quality-related fields
SELECT column_name, data_type FROM information_schema.columns 
WHERE table_name = 'scans';

-- Check for negative noise values
SELECT MIN((cloud_metrics->>'Noise_Db')::numeric), MAX((cloud_metrics->>'Noise_Db')::numeric)
FROM pointcloud;

-- Check if there's a pattern where Cover_Pct could be interpreted differently
SELECT p.cloud_metrics->>'Cover_Pct', p.cloud_metrics->>'Ref_Pct', p.cloud_metrics->>'Lap_Pct'
FROM pointcloud p LIMIT 10;

-- Check if scans table has any numeric-like data in text fields that could be parsed
SELECT s.questregistry, s.size, s.scan_cost, s.scanning_rate
FROM scans s LIMIT 5;
